from pathlib import Path
import base64, re, json
import numpy as np
import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.ticker import FuncFormatter

ROOT=Path(__file__).resolve().parent
d=pd.read_csv(ROOT/'data_cleaned.csv')
out=ROOT/'eda_figures';out.mkdir(exist_ok=True)
plt.rcParams.update({'figure.facecolor':'#141b23','axes.facecolor':'#141b23','text.color':'#f5f7fa','axes.labelcolor':'#dbe4ed','xtick.color':'#dbe4ed','ytick.color':'#dbe4ed','axes.edgecolor':'#526270','font.size':11,'savefig.facecolor':'#141b23'})
green='#c1f769';blue='#74c8ff';cards=[]
def finish(num,title,obs,interpret,implication,note):
    fig=plt.gcf();fig.tight_layout(pad=2);p=out/f'chart_{num:02}.png';fig.savefig(p,dpi=145);plt.close(fig)
    data=base64.b64encode(p.read_bytes()).decode()
    cards.append(f'<section id="chart{num}"><div class="eyebrow">Chart {num:02}</div><h2>{title}</h2><figure><img src="data:image/png;base64,{data}" alt="{title}. {obs}"><figcaption>{note}</figcaption></figure><p><strong>Observation →</strong> {obs}</p><p><strong>Interpretation →</strong> {interpret}</p><p><strong>Research Implication →</strong> {implication}</p></section>')
money=FuncFormatter(lambda v,pos:f'${v:,.0f}')
fig,ax=plt.subplots(1,2,figsize=(12,4.8));ax[0].hist(d.msrp,bins=50,color=green);ax[0].set(xlabel='Recorded MSRP (USD)',ylabel='Records',title='Original dollar scale');ax[0].ticklabel_format(axis='x',style='sci',scilimits=(6,6));ax[1].hist(np.log10(d.msrp),bins=40,color=blue);ax[1].set(xlabel='log10(recorded MSRP)',ylabel='Records',title='Same records, logarithmic transformation')
finish(1,'Price distribution: a long upper tail',f'Mean recorded MSRP is ${d.msrp.mean():,.0f}, above the ${d.msrp.median():,.0f} median. The maximum is ${d.msrp.max():,}.','A small number of expensive records pull the mean upward. The log transformation makes the central distribution easier to inspect.','Report the median and IQR alongside the mean, and compare raw-price and log-price models.','All 11,199 cleaned records. Equal-width bins within each scale. No prices removed or capped.')
fig,ax=plt.subplots(figsize=(10,4.8));ax.hist(d.engine_hp.dropna(),bins=35,color=green);ax.set(xlabel='Engine horsepower (HP)',ylabel='Records')
finish(2,'Horsepower distribution',f'Median horsepower is {d.engine_hp.median():.0f} HP. The middle half spans {d.engine_hp.quantile(.25):.0f}–{d.engine_hp.quantile(.75):.0f} HP, and the maximum is {d.engine_hp.max():.0f} HP.','Most records have moderate power, with a smaller high-performance tail.','Use horsepower as a candidate explanatory variable and check whether extreme values dominate its relationship with price.','11,130 records with horsepower. 69 missing values excluded, without imputation.')
groups=['compact','midsize','large'];fig,ax=plt.subplots(figsize=(10,5));ax.boxplot([d.loc[d.vehicle_size==g,'msrp'] for g in groups],tick_labels=[f'{g.title()}\nn={(d.vehicle_size==g).sum():,}' for g in groups],patch_artist=True,boxprops={'facecolor':green},medianprops={'color':'#111'},flierprops={'markeredgecolor':blue,'markersize':3});ax.set_yscale('log');ax.yaxis.set_major_formatter(money);ax.set(ylabel='Recorded MSRP (USD, log scale)')
finish(3,'Price differences across vehicle sizes','Median recorded prices are $23,650 for compact, $33,295 for midsize, and $39,970 for large vehicles.','Larger categories have higher medians, but their distributions overlap. Size alone does not explain price.','Compare size groups while accounting for horsepower, brand, and model year in later analysis.','All 11,199 records. Boxes show Q1–Q3 and median. Whiskers use 1.5×IQR within groups on original prices; dots are retained outliers. Log axis changes display only.')
p=d.dropna(subset=['engine_hp','msrp']);fig,ax=plt.subplots(figsize=(10,5));ax.scatter(p.engine_hp,p.msrp,s=7,alpha=.18,color=green,rasterized=True);ax.set_yscale('log');ax.yaxis.set_major_formatter(money);ax.set(xlabel='Engine horsepower (HP)',ylabel='Recorded MSRP (USD, log scale)')
finish(4,'Horsepower and price',f'Pearson correlation is {p.engine_hp.corr(p.msrp):.3f} for horsepower and MSRP, and {p.engine_hp.corr(np.log10(p.msrp)):.3f} for horsepower and log10(MSRP).','Higher-power records generally cost more, with substantial price variation at similar horsepower. Correlation does not establish causation.','Evaluate horsepower with brand, size, and year controls. Compare results after excluding flagged price-floor records.','All 11,130 complete horsepower–price pairs plotted. Transparent points reveal overlap. Correlations use original numeric values or the specified log transformation.')
cols=['year','engine_hp','engine_cylinders','city_mpg','highway_mpg','log10_msrp'];c=d.loc[d.fuel_economy_analysis_ready,cols].dropna();corr=c.corr();fig,ax=plt.subplots(figsize=(10,6));im=ax.imshow(corr,vmin=-1,vmax=1,cmap='RdBu_r');labels=['Year','HP','Cylinders','City MPG','Highway MPG','log10 MSRP'];ax.set_xticks(range(6),labels,rotation=25,ha='right');ax.set_yticks(range(6),labels)
for i in range(6):
    for j in range(6):ax.text(j,i,f'{corr.iloc[i,j]:.2f}',ha='center',va='center',color='black' if abs(corr.iloc[i,j])<.55 else 'white')
fig.colorbar(im,ax=ax,label='Pearson r')
finish(5,'Correlations among numeric features',f'City and highway MPG have r={corr.loc["city_mpg","highway_mpg"]:.3f}. Horsepower and highway MPG have r={corr.loc["engine_hp","highway_mpg"]:.3f}.','Fuel-economy measures overlap strongly. The power–efficiency relationship may reflect vehicle design and group composition.','Check redundant predictors before modeling and avoid interpreting any correlation as an independent causal effect.',f'{len(c):,} complete cases across these six variables, restricted to the existing known non-electric fuel-economy subset. A common subset makes matrix entries comparable.')
y=d.groupby('year').msrp.agg(['median','size']);fig,ax=plt.subplots(2,1,figsize=(11,6),sharex=True,gridspec_kw={'height_ratios':[2,1]});ax[0].plot(y.index,y['median'],color=green,marker='o',ms=4);ax[0].yaxis.set_major_formatter(money);ax[0].set(ylabel='Median recorded MSRP');ax[1].bar(y.index,y['size'],color=blue);ax[1].set(xlabel='Model year',ylabel='Records')
finish(6,'Model-year patterns and uneven coverage','Median MSRP rises from $2,561 in model year 2000 to $22,768 in 2001. Model years 2015–2017 contribute 5,763 records.','The abrupt price shift and uneven year coverage suggest source-price construction and sample composition need review. This is a cross-sectional model-year comparison, not repeated observations of the same cars.','Avoid claiming historical market price growth. Compare within model-year groups and examine the $2,000 source-price floor.','All 11,199 records grouped by model year (1990–2017). Prices are not inflation-adjusted. The lower panel shows each group denominator.')
f=d[d.fuel_economy_analysis_ready & d.transmission.notna()];g=f.groupby('transmission').highway_mpg.agg(['median','count']).sort_values('median');fig,ax=plt.subplots(figsize=(10,4.8));bars=ax.barh([f'{a}\n(n={int(r["count"]):,})' for a,r in g.iterrows()],g['median'],color=green);ax.bar_label(bars,fmt='%.1f',padding=5,color='white');ax.set(xlabel='Median highway MPG',xlim=(0,52))
finish(7,'Fuel economy by transmission','Median highway MPG is 25 for automatic, 26 for manual, 30 for automated manual, and 44.5 for direct drive. Direct drive has only two eligible records.','Group sizes differ greatly. The two-record direct-drive result is unstable and should not be generalized.','Use well-supported groups for later comparisons and account for fuel type, year, and vehicle size.','Known non-electric fuel-economy subset, excluding missing transmission. All eligible records used in each group. No electric efficiency values mixed into MPG comparisons.')
original=['make','model','year','fuel_type','engine_hp','engine_cylinders','transmission','driven_wheels','doors','market_category','vehicle_size','vehicle_style','highway_mpg','city_mpg','popularity','msrp'];m=d[original].isna().sum().sort_values();fig,ax=plt.subplots(figsize=(11,6));bars=ax.barh(m.index,m/len(d)*100,color=blue);ax.bar_label(bars,labels=[f'{v:,} ({v/len(d)*100:.2f}%)' for v in m],padding=4,color='white',fontsize=9);ax.set(xlabel='Missing values (% of 11,199 records)',xlim=(0,39))
finish(8,'Missing values by field','Market category is missing in 3,376 records (30.15%). Horsepower is missing in 69, cylinders in 30, transmission in 12, doors in 6, fuel type in 3, and highway MPG in 1.','Missingness is concentrated in specific fields. Complete-case filtering across every variable would discard many usable records.','Use only the fields required for each analysis and report its denominator. Avoid requiring market category for the main price analysis.','All 16 original fields in the cleaned dataset. Missing category markers normalized in Assignment 3 count as missing here; this is not the raw-data missingness count.')
t=d.assign(fuel_group=np.where(d.fuel_type.eq('electric'),'Electric',np.where(d.fuel_type.isna(),'Unknown fuel','Known non-electric'))).groupby('fuel_group').engine_hp.agg(['size','count']);fig,ax=plt.subplots(figsize=(10,4.8));pct=100*(t['size']-t['count'])/t['size'];bars=ax.barh(t.index,pct,color=green);ax.bar_label(bars,labels=[f'{int(r["size"]-r["count"])}/{int(r["size"]):,} ({pct.loc[k]:.1f}%)' for k,r in t.iterrows()],padding=4,color='white');ax.set(xlabel='Records missing horsepower (%)',xlim=(0,85))
finish(9,'Horsepower missingness differs by fuel group','Horsepower is missing for 44 of 66 electric records (66.7%), compared with 25 of 11,130 known non-electric records (0.22%). None of the three unknown-fuel records lacks horsepower.','Dropping missing horsepower disproportionately removes electric records. Missingness is associated with fuel group.','Describe the selection bias in horsepower-based findings. Analyze electric vehicles separately if their power and efficiency units can be verified.','All 11,199 records assigned to mutually exclusive fuel groups. Bar labels show missing/total. This descriptive comparison does not prove a missing-data mechanism.')
q1,q3=d.msrp.quantile([.25,.75]);fence=q3+1.5*(q3-q1);counts=pd.Series({'MSRP = $2,000 floor':int((d.msrp==2000).sum()),'MSRP above IQR fence':int((d.msrp>fence).sum()),'Electric efficiency review':int(d.electric_efficiency_review_flag.sum()),'Highway value quarantined':int(d.highway_mpg_review_flag.sum())});fig,ax=plt.subplots(figsize=(11,4.8));bars=ax.barh(counts.index,counts,color=blue);ax.bar_label(bars,padding=4,color='white');ax.set(xlabel='Records flagged for review (flags may overlap)',xlim=(0,1100))
finish(10,'Outliers and potential anomalies','There are 960 MSRP values above the $75,182 upper IQR fence and 748 records at exactly $2,000. There are also 66 electric-efficiency review flags and one quarantined highway value.','Extreme prices may be valid luxury vehicles. The repeated minimum and questionable efficiency values require source review, rather than automatic deletion.','Run sensitivity analyses with and without price-floor and price-outlier records. Keep electric efficiency separate until units are confirmed.','MSRP fence = Q3 + 1.5×IQR from all cleaned prices. Flags are not mutually exclusive. The quarantined highway value is already missing in the cleaned data. Other flagged records remain retained.')
findings=[
'Recorded MSRP is right-skewed. Its mean is $41,926 and median is $30,675. Robust summaries and log-price analysis will reduce dependence on the upper tail (Charts 1 and 10).',
'Horsepower is positively associated with price: Pearson r = 0.659 on recorded MSRP and 0.685 on log10(MSRP), using 11,130 complete pairs. Later models should account for brand, size, and year (Chart 4).',
'Median recorded price increases from compact ($23,650) to midsize ($33,295) to large ($39,970). Overlapping distributions show that size does not fully explain price (Chart 3).',
'Model-year prices show an abrupt shift around 2001, while 2015–2017 supply 51.46% of the records. Year comparisons require source-price and composition checks before any trend claim (Chart 6).',
'Missingness is uneven: 30.15% lack market category, and 66.7% of electric records lack horsepower versus 0.22% of known non-electric records. Analysis-specific subsets and explicit denominators are essential (Charts 8 and 9).']
